function check(input, actual, expected) {
  const n = input[0];
  if (!Array.isArray(actual) || actual.length !== n) return false;
  const position = new Array(n + 1).fill(-1);
  for (let index = 0; index < n; index++) {
    const value = actual[index];
    if (!Number.isInteger(value) || value < 1 || value > n || position[value] !== -1) return false;
    position[value] = index;
  }
  // For each pair, an integer average placed strictly between them breaks the rule.
  for (let i = 0; i < n; i++) {
    for (let j = i + 2; j < n; j++) {
      const total = actual[i] + actual[j];
      if (total % 2 !== 0) continue;
      const middle = position[total / 2];
      if (middle > i && middle < j) return false;
    }
  }
  return true;
}

