function beautifulArray(n) {
  const memo = new Map();

  function build(size) {
    if (size === 1) {
      return [1];
    }
    if (memo.has(size)) {
      return memo.get(size);
    }
    const odds = build(Math.ceil(size / 2)).map((value) => 2 * value - 1);
    const evens = build(Math.floor(size / 2)).map((value) => 2 * value);
    const result = [...odds, ...evens];
    memo.set(size, result);
    return result;
  }

  return build(n);
}

