function beautifulArray(n) {
  // Backtracking: place values left to right, skipping any value that would be the far end of a bad triple.
  const order = [];
  const used = new Array(n + 1).fill(false);
  const fits = (value) => {
    for (let i = 0; i < order.length; i++)
      for (let k = i + 1; k < order.length; k++)
        if (2 * order[k] === order[i] + value) return false;
    return true;
  };
  const place = () => {
    if (order.length === n) return true;
    for (let value = 1; value <= n; value++) {
      if (used[value] || !fits(value)) continue;
      used[value] = true;
      order.push(value);
      if (place()) return true;
      used[value] = false;
      order.pop();
    }
    return false;
  };
  place();
  return order;
}

